// Choix: batch_15, batch_30, fail_second_batch, zero, test_15
const selected = 'batch_15';
const scenarios = {
  batch_15: { message_count: 15, fail_batch: null, test_mode: false },
  batch_30: { message_count: 30, fail_batch: null, test_mode: false },
  fail_second_batch: { message_count: 15, fail_batch: 2, test_mode: false },
  zero: { message_count: 0, fail_batch: null, test_mode: false },
  test_15: { message_count: 15, fail_batch: null, test_mode: true },
};
const scenario = scenarios[selected];
if (!scenario) throw new Error(`Scénario inconnu: ${selected}`);
return [{ json: {
  scenario: selected,
  ...scenario,
  expected_batches: Math.ceil(scenario.message_count / 10),
  user_id: '00000000-0000-4000-8000-000000000001',
  cursor_after: `cursor-http-fixture-${selected}`,
} }];

const config = $json;
if (config.message_count === 0) return [{ json: { _empty: true, _sync: config._sync, _scenario: config } }];
return Array.from({ length: config.message_count }, (_, index) => ({ json: {
  gmail_message_id: `http-fixture-message-${String(index + 1).padStart(3, '0')}`,
  attempt: 0,
  _sync: config._sync,
  _scenario: config,
} }));

const item = $json;
const sequence = Number(item.gmail_message_id.split('-').at(-1));
return [{ json: {
  _sync: item._sync,
  _scenario: item._scenario,
  gmail_message_id: item.gmail_message_id,
  gmail_thread_id: `fixture-thread-${String(Math.ceil(sequence / 3)).padStart(3, '0')}`,
  message_id: `<${item.gmail_message_id}@mailflow.invalid>`,
  sender: `expediteur${sequence}@example.test`,
  recipients: ['mailflow-test@example.test'],
  subject: `Message Gmail fictif ${sequence}`,
  body_text: `Contenu fictif du message ${sequence}.`,
  body_html: null,
  received_at: new Date(Date.UTC(2026, 0, 1, 8, sequence)).toISOString(),
} }];

const items = $input.all();
const sync = items[0]?.json?._sync;
const scenario = items[0]?.json?._scenario;
if (!sync || !scenario) throw new Error('Contexte de test absent.');
if (items.length > 10) throw new Error(`Lot trop grand: ${items.length}`);
const messages = items.map(({ json: value }) => ({
  gmail_message_id: value.gmail_message_id, gmail_thread_id: value.gmail_thread_id,
  message_id: value.message_id, sender: value.sender, recipients: value.recipients,
  subject: value.subject, body_text: value.body_text, body_html: value.body_html, received_at: value.received_at,
}));
const sequence = Number(messages[0].gmail_message_id.split('-').at(-1));
return [{ json: { _sync: sync, _scenario: scenario, batch_number: Math.floor((sequence - 1) / 10) + 1, messages } }];

const batch = $json;
if (batch.classification_tasks.length !== batch.received_count) throw new Error('Nombre de tâches de classification inattendu.');
return batch.classification_tasks.map((task) => ({ json: {
  _sync: batch._sync, _scenario: batch._scenario, classification_task: task,
  _batch: {
    _sync: batch._sync, _scenario: batch._scenario, batch_number: batch.batch_number,
    imported_count: batch.imported_count, duplicate_count: batch.duplicate_count,
    received_count: batch.received_count, expected_classifications: batch.classification_tasks.length,
  },
} }));

const items = $input.all();
const batch = items[0]?.json?._batch;
if (!batch) throw new Error('Contexte du lot absent.');
if (items.length !== batch.expected_classifications) throw new Error(`Classifications perdues: ${items.length}/${batch.expected_classifications}`);
return [{ json: {
  _sync: batch._sync, _scenario: batch._scenario, batch_number: batch.batch_number,
  imported_count: batch.imported_count, duplicate_count: batch.duplicate_count,
  classification_count: items.length, batch_size: batch.received_count,
} }];

const items = $input.all();
const first = items[0]?.json;
if (!first) throw new Error('Aucun résultat de lot.');
const scenario = first._scenario;
const sizes = items.map((item) => item.json.batch_size);
const imported = items.reduce((sum, item) => sum + item.json.imported_count, 0);
const duplicates = items.reduce((sum, item) => sum + item.json.duplicate_count, 0);
const classifications = items.reduce((sum, item) => sum + item.json.classification_count, 0);
if (items.length !== scenario.expected_batches) throw new Error(`Lots HTTP: ${items.length}/${scenario.expected_batches}`);
if (imported + duplicates !== scenario.message_count) throw new Error('Compteurs HTTP incohérents.');
if (classifications !== scenario.message_count) throw new Error(`Classifications: ${classifications}/${scenario.message_count}`);
return [{ json: {
  _sync: first._sync, scenario: scenario.scenario, batch_sizes: sizes,
  http_import_request_count: items.length, imported_count: imported,
  duplicate_count: duplicates, classification_count: classifications,
} }];

const item = $json;
return [{ json: {
  _sync: item._sync, scenario: item._scenario.scenario, batch_sizes: [],
  http_import_request_count: 0, imported_count: 0, duplicate_count: 0, classification_count: 0,
} }];

const summary = $json;
const sync = summary._sync;
if (sync.test_mode || !sync.execution_id || !sync.idempotency_key) throw new Error('Commit interdit ou contexte incomplet.');
return [{ json: {
  _summary: summary,
  user_id: sync.user_id, execution_id: sync.execution_id,
  cursor_before: sync.cursor_before, cursor_after: sync.cursor_after,
  idempotency_key: sync.idempotency_key, imported_count: summary.imported_count,
} }];

const config = $('Configurer scénario').first().json;
const response = $json;
if (response.user_id !== config.user_id) throw new Error('Réponse FastAPI associée au mauvais utilisateur fictif.');
if (!config.test_mode && !response.execution_id) throw new Error('execution_id absent de la réservation.');
return [{ json: { ...config, _sync: {
  user_id: config.user_id,
  execution_id: response.execution_id || null,
  idempotency_key: config.test_mode ? null : `gmail-sync-http-test:${$execution.id}`,
  cursor_before: response.cursor || null,
  cursor_after: config.cursor_after,
  mode: 'http-fixture',
  test_mode: config.test_mode,
  classify_in_test_mode: true,
} } }];

const batch = $('Préparer lot import').item.json;
const response = $json;
if (response.received_count !== batch.messages.length) throw new Error('received_count HTTP incohérent.');
if (!Number.isInteger(response.imported_count) || response.imported_count < 0) throw new Error('imported_count HTTP invalide.');
if (!Array.isArray(response.classification_tasks)) throw new Error('classification_tasks HTTP invalide.');
return [{ json: {
  _sync: batch._sync, _scenario: batch._scenario, batch_number: batch.batch_number,
  received_count: response.received_count, imported_count: response.imported_count,
  duplicate_count: response.duplicate_count, classification_tasks: response.classification_tasks,
} }];
